/**
 * Petshop Spalvų Swatch Burbuliukai v1 (pa_spalva)
 * Paverčia variable produktų pa_spalva dropdown į spalvotus burbuliukus.
 * Naudoja term meta 'product_attribute_color' (hex). Neturimos spalvos rodomos perbrauktos.
 * Scope: front-end. Veikia visoms variable prekėms su pa_spalva atributu.
 */
add_action('wp_footer', function(){
    if (!function_exists('is_product') || !is_product()) return;

    // Surenkam slug -> hex žemėlapį iš pa_spalva terminų
    $map = array();
    if (taxonomy_exists('pa_spalva')) {
        $terms = get_terms(array('taxonomy'=>'pa_spalva','hide_empty'=>false));
        foreach ((array)$terms as $t) {
            $hex = get_term_meta($t->term_id, 'product_attribute_color', true);
            if ($hex) $map[$t->slug] = $hex;
        }
    }
    if (empty($map)) return;
    ?>
    <style>
    .psc-swatches{display:flex;gap:10px;flex-wrap:wrap;margin:4px 0 10px;align-items:center;}
    .psc-swatch{width:32px;height:32px;border-radius:50%;cursor:pointer;border:2px solid #ddd;
        box-shadow:inset 0 0 0 2px #fff;transition:transform .12s ease,border-color .12s ease;position:relative;}
    .psc-swatch:hover{transform:scale(1.12);}
    .psc-swatch.active{border-color:#2f5a3a;box-shadow:inset 0 0 0 2px #fff,0 0 0 1px #2f5a3a;}
    .psc-swatch.psc-oos{opacity:.4;cursor:not-allowed;}
    .psc-swatch.psc-oos::after{content:"";position:absolute;top:50%;left:-3px;right:-3px;height:2px;
        background:#c0392b;transform:rotate(-45deg);}
    .psc-swatch-label{font-size:14px;color:#333;margin-left:6px;font-weight:500;}
    .psc-swatch-label .psc-oos-txt{color:#c0392b;font-weight:400;}
    /* paslepiam originalų select bet paliekam DOM'e WC logikai */
    .variations td.value select.psc-hidden{position:absolute;opacity:0;height:0;width:0;pointer-events:none;margin:0;}
    </style>
    <script>
    (function(){
        var MAP = <?php echo wp_json_encode($map); ?>;
        function initSwatches(){
            if (!window.jQuery) { return; }
            var $ = window.jQuery;
            $('.variations select').each(function(){
                var sel = this, $sel = $(sel);
                var name = sel.getAttribute('name') || '';
                if (name.indexOf('spalva') === -1) return;        // tik spalva
                if ($sel.data('psc-done')) return;
                $sel.data('psc-done', 1);

                var $form = $sel.closest('form.variations_form');
                var variations = $form.length ? $form.data('product_variations') : null;

                var $wrap = $('<div class="psc-swatches"></div>');
                var $label = $('<span class="psc-swatch-label"></span>');

                $sel.find('option').each(function(){
                    var val = this.value, txt = this.textContent;
                    if (!val) return;                              // praleidžiam "Pasirinkite savybę"
                    var hex = MAP[val] || '#cccccc';
                    var $b = $('<span class="psc-swatch"></span>').css('background', hex).attr('title', txt).attr('data-value', val).attr('data-name', txt);

                    // ar neturima (out of stock)
                    var oos = false;
                    if (variations && variations.length){
                        for (var i=0;i<variations.length;i++){
                            var a = variations[i].attributes || {};
                            if (a['attribute_pa_spalva'] === val){
                                if (variations[i].is_in_stock === false || variations[i].is_purchasable === false) oos = true;
                                break;
                            }
                        }
                    }
                    if (oos) $b.addClass('psc-oos');

                    $b.on('click', function(){
                        if ($(this).hasClass('psc-oos')) return;
                        $sel.val(val).trigger('change');
                        $wrap.find('.psc-swatch').removeClass('active');
                        $(this).addClass('active');
                        $label.html(txt);
                    });
                    $wrap.append($b);
                });

                $wrap.append($label);
                $sel.addClass('psc-hidden');
                $sel.before($wrap);
            });
        }
        if (window.jQuery){
            jQuery(document).ready(initSwatches);
            jQuery(document).on('wc_variation_form', initSwatches);
        } else {
            document.addEventListener('DOMContentLoaded', function(){ setTimeout(initSwatches, 500); });
        }
    })();
    </script>
    <?php
}, 99);

